package com.oms.dao;
import java.math.BigDecimal;import java.sql.*;import java.time.LocalDateTime;import java.util.*;
public class InventoryCountDao{
 public record Warehouse(long id,String code,String name){} public record Line(long productId,String sku,String product,String unit,BigDecimal systemQuantity,BigDecimal actualQuantity){} public record Count(long id,String code,long warehouseId,String warehouse,String status,String note,LocalDateTime createdAt,List<Line> lines){} public record PageData(List<Warehouse> warehouses,List<Count> counts){}
 public PageData page(Connection c)throws SQLException{List<Warehouse>w=new ArrayList<>();try(var p=c.prepareStatement("SELECT id,code,name FROM warehouses WHERE status='ACTIVE' ORDER BY code");var r=p.executeQuery()){while(r.next())w.add(new Warehouse(r.getLong(1),r.getString(2),r.getString(3)));}List<Count>x=new ArrayList<>();try(var p=c.prepareStatement("SELECT k.id,k.code,k.warehouse_id,w.code,k.status,k.note,k.created_at FROM inventory_counts k JOIN warehouses w ON w.id=k.warehouse_id ORDER BY k.id DESC LIMIT 30");var r=p.executeQuery()){while(r.next()){Count k=new Count(r.getLong(1),r.getString(2),r.getLong(3),r.getString(4),r.getString(5),r.getString(6),r.getTimestamp(7).toLocalDateTime(),new ArrayList<>());lines(c,k);x.add(k);}}return new PageData(w,x);}
 private void lines(Connection c,Count k)throws SQLException{try(var p=c.prepareStatement("SELECT l.product_id,p.sku,p.name,u.name,l.system_quantity,l.actual_quantity FROM inventory_count_lines l JOIN products p ON p.id=l.product_id JOIN units u ON u.id=p.base_unit_id WHERE l.count_id=? ORDER BY l.product_id")){p.setLong(1,k.id());try(var r=p.executeQuery()){while(r.next())k.lines().add(new Line(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getBigDecimal(6)));}}}
 public long next(Connection c)throws SQLException{long n;try(var p=c.prepareStatement("SELECT last_number FROM document_sequences WHERE name='INVENTORY_COUNT' FOR UPDATE");var r=p.executeQuery()){if(!r.next())throw new SQLException("Thiếu dãy kiểm kê");n=r.getLong(1)+1;}try(var p=c.prepareStatement("UPDATE document_sequences SET last_number=? WHERE name='INVENTORY_COUNT'")){p.setLong(1,n);p.executeUpdate();}return n;}
 public long create(Connection c,String code,long warehouse,String note,long actor)throws SQLException{long id;try(var p=c.prepareStatement("INSERT INTO inventory_counts(code,warehouse_id,note,created_by) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,code);p.setLong(2,warehouse);p.setString(3,note);p.setLong(4,actor);p.executeUpdate();try(var r=p.getGeneratedKeys()){r.next();id=r.getLong(1);}}try(var p=c.prepareStatement("INSERT INTO inventory_count_lines(count_id,product_id,system_quantity) SELECT ?,p.id,COALESCE(i.on_hand,0) FROM products p LEFT JOIN warehouse_inventory i ON i.product_id=p.id AND i.warehouse_id=? WHERE p.status='ACTIVE'")){p.setLong(1,id);p.setLong(2,warehouse);p.executeUpdate();}return id;}
 public Count lock(Connection c,long id)throws SQLException{try(var p=c.prepareStatement("SELECT k.id,k.code,k.warehouse_id,w.code,k.status,k.note,k.created_at FROM inventory_counts k JOIN warehouses w ON w.id=k.warehouse_id WHERE k.id=? FOR UPDATE")){p.setLong(1,id);try(var r=p.executeQuery()){if(!r.next())return null;Count k=new Count(r.getLong(1),r.getString(2),r.getLong(3),r.getString(4),r.getString(5),r.getString(6),r.getTimestamp(7).toLocalDateTime(),new ArrayList<>());lines(c,k);return k;}}}
 public void saveActual(Connection c,long id,List<BigDecimal> actual)throws SQLException{try(var select=c.prepareStatement("SELECT id FROM inventory_count_lines WHERE count_id=? ORDER BY product_id FOR UPDATE")){select.setLong(1,id);try(var r=select.executeQuery()){int i=0;while(r.next()){try(var p=c.prepareStatement("UPDATE inventory_count_lines SET actual_quantity=? WHERE id=?")){p.setBigDecimal(1,actual.get(i++));p.setLong(2,r.getLong(1));p.executeUpdate();}}if(i!=actual.size())throw new IllegalStateException("Số dòng kiểm kê đã thay đổi.");}}try(var p=c.prepareStatement("UPDATE inventory_counts SET status='COUNTED' WHERE id=? AND status IN ('DRAFT','COUNTED')")){p.setLong(1,id);p.executeUpdate();}}
 public void post(Connection c,Count k,long actor)throws SQLException{for(Line l:k.lines()){if(l.actualQuantity()==null)throw new IllegalStateException("Chưa nhập đủ số thực tế.");BigDecimal current=BigDecimal.ZERO,reserved=BigDecimal.ZERO;try(var lock=c.prepareStatement("SELECT on_hand,reserved FROM warehouse_inventory WHERE warehouse_id=? AND product_id=? FOR UPDATE")){lock.setLong(1,k.warehouseId());lock.setLong(2,l.productId());try(var r=lock.executeQuery()){if(r.next()){current=r.getBigDecimal(1);reserved=r.getBigDecimal(2);}}}if(l.actualQuantity().compareTo(reserved)<0)throw new IllegalStateException("Tồn thực tế "+l.sku()+" thấp hơn lượng đang giữ chỗ.");try(var p=c.prepareStatement("INSERT INTO warehouse_inventory(warehouse_id,product_id,on_hand,reserved) VALUES(?,?,?,0) ON DUPLICATE KEY UPDATE on_hand=VALUES(on_hand)")){p.setLong(1,k.warehouseId());p.setLong(2,l.productId());p.setBigDecimal(3,l.actualQuantity());p.executeUpdate();}BigDecimal d=l.actualQuantity().subtract(current);if(d.signum()!=0){try(var p=c.prepareStatement("INSERT INTO inventory_movements(warehouse_id,product_id,unit_id,quantity,movement_type,reference_type,reference_id,created_by) SELECT ?,id,base_unit_id,?,?, 'INVENTORY_COUNT',?,? FROM products WHERE id=?")){p.setLong(1,k.warehouseId());p.setBigDecimal(2,d.abs());p.setString(3,d.signum()>0?"INVENTORY_COUNT_GAIN":"INVENTORY_COUNT_LOSS");p.setLong(4,k.id());p.setLong(5,actor);p.setLong(6,l.productId());p.executeUpdate();}}}try(var p=c.prepareStatement("UPDATE inventory_counts SET status='POSTED',posted_by=?,posted_at=CURRENT_TIMESTAMP WHERE id=? AND status='COUNTED'")){p.setLong(1,actor);p.setLong(2,k.id());if(p.executeUpdate()!=1)throw new SQLException("Phiếu kiểm kê đã thay đổi trạng thái");}}
}
